-- 为 ElementUI 表单组件配置 PropertyConfigJson（右侧属性面板动态渲染）
-- 格式：DynPropContainer -> DynPropItem[] -> DynPropControl

-- DynElInput 输入框
UPDATE ComponentMeta SET PropertyConfigJson = '{"component":"DynPropContainer","options":{"itemoptions":{"style":{"padding":"0 8px"}},"childrenctrls":[{"component":"DynPropItem","modelname":"options.comoptions.placeholder","options":{"comoptions":{},"labeloptions":{"label":"占位符","show":true,"labelwidth":"80px"},"itemoptions":{"style":{"marginBottom":"8px"}}},"childrenctrls":[{"component":"DynPropControl","modelname":"","options":{"comoptions":{"kind":"input","default":""},"itemoptions":{"style":{}}},"childrenctrls":[]}]},{"component":"DynPropItem","modelname":"options.comoptions.clearable","options":{"comoptions":{},"labeloptions":{"label":"可清除","show":true,"labelwidth":"80px"},"itemoptions":{"style":{"marginBottom":"8px"}}},"childrenctrls":[{"component":"DynPropControl","modelname":"","options":{"comoptions":{"kind":"switch","default":true},"itemoptions":{"style":{}}},"childrenctrls":[]}]},{"component":"DynPropItem","modelname":"options.comoptions.disabled","options":{"comoptions":{},"labeloptions":{"label":"禁用","show":true,"labelwidth":"80px"},"itemoptions":{"style":{"marginBottom":"8px"}}},"childrenctrls":[{"component":"DynPropControl","modelname":"","options":{"comoptions":{"kind":"switch","default":false},"itemoptions":{"style":{}}},"childrenctrls":[]}]},{"component":"DynPropItem","modelname":"options.comoptions.readonly","options":{"comoptions":{},"labeloptions":{"label":"只读","show":true,"labelwidth":"80px"},"itemoptions":{"style":{"marginBottom":"8px"}}},"childrenctrls":[{"component":"DynPropControl","modelname":"","options":{"comoptions":{"kind":"switch","default":false},"itemoptions":{"style":{}}},"childrenctrls":[]}]},{"component":"DynPropItem","modelname":"options.comoptions.maxlength","options":{"comoptions":{},"labeloptions":{"label":"最大长度","show":true,"labelwidth":"80px"},"itemoptions":{"style":{"marginBottom":"8px"}}},"childrenctrls":[{"component":"DynPropControl","modelname":"","options":{"comoptions":{"kind":"number","default":200},"itemoptions":{"style":{}}},"childrenctrls":[]}]}]}' WHERE ComponentName = 'DynElInput';

